const secret = $env.N8N_WEBHOOK_SECRET;
const timestamp = $headers['x-lendloop-timestamp'];
const eventId = $headers['x-lendloop-event-id'];
const signature = String($headers['x-lendloop-signature'] || '').replace('sha256=', '');
const crypto = require('crypto');
const rawBody = typeof $rawBody === 'string' ? $rawBody : JSON.stringify($json);
if (!timestamp || !eventId || !secret) throw new Error('Missing signed webhook fields');
if (Math.abs(Date.now() - Number(timestamp)) > 300000) throw new Error('Replay-protected timestamp rejected');
const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + rawBody).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'))) throw new Error('Invalid HMAC signature');
return [{ json: $json }];

const event = $json;
console.log(`[LendLoop notification] ${event.type} for loan ${event.loanId}`);
return [{ json: { eventId: event.eventId, delivered: true, recipientId: event.recipientId } }];
